mapper.select:
SELECT COUNT(*) FROM ai_follow_up f JOIN ai_task t ON t.owner_id=f.owner_id AND t.id=f.task_id
WHERE f.owner_id=#{owner} AND f.session_id=#{sessionId} AND f.root_question_id=#{rootQuestionId}
  AND t.status IN ('QUEUED','RUNNING','VALIDATING','CANCEL_REQUESTED')
AND f.task_id <> #{excludedTaskId}

SELECT t.id,t.purpose,t.status,t.revision,t.title,t.provider,t.model,t.currency,t.attempt_count,t.created_at,t.updated_at,t.error_code
FROM ai_follow_up f JOIN ai_task t ON t.owner_id=f.owner_id AND t.id=f.task_id
WHERE f.owner_id=#{owner} AND f.session_id=#{sessionId} AND t.purpose='FOLLOW_UP'
AND t.id > #{cursor}
ORDER BY t.id LIMIT #{limit}

SELECT id,purpose,status,revision,title,provider,model,currency,attempt_count,created_at,updated_at,error_code
FROM ai_task WHERE owner_id=#{owner}
AND id > #{cursor}
ORDER BY id LIMIT #{limit}

SELECT id,purpose,status,revision,title,provider,model,currency,attempt_count,created_at,updated_at,error_code
FROM ai_task WHERE owner_id=#{owner} AND purpose='RELATION_DRAFT' AND status='SUCCEEDED'
AND id > #{cursor}
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE ai_task SET status=#{task.status},revision=#{task.revision},authorization_epoch=#{task.authorizationEpoch},
  current_attempt_id=#{task.currentAttemptId},attempt_count=#{task.attemptCount},candidate_json=#{task.candidateJson},
  error_code=#{task.errorCode},updated_at=#{task.updatedAt}
WHERE owner_id=#{task.ownerId} AND id=#{task.id} AND revision=#{expected}

UPDATE ai_attempt SET status=#{attempt.status},fee_status=#{attempt.feeStatus},accounted_micros=#{attempt.accountedMicros},
  prompt_tokens=#{attempt.promptTokens},completion_tokens=#{attempt.completionTokens},provider_request_id=#{attempt.providerRequestId},
  error_code=#{attempt.errorCode},reconciliation_note=#{attempt.reconciliationNote},budget_date=#{attempt.budgetDate},
  claim_token=#{attempt.claimToken},runtime_epoch=#{attempt.runtimeEpoch},lease_until=#{attempt.leaseUntil},
  sent_at=#{attempt.sentAt},finished_at=#{attempt.finishedAt}
WHERE owner_id=#{attempt.ownerId} AND task_id=#{attempt.taskId} AND id=#{attempt.id} AND status=#{expectedStatus}
  AND claim_token <=> #{expectedToken}

mapper.select:
SELECT d.task_id,d.target_version_id,v.version_number AS target_version_number,d.created_at AS adopted_at,t.manifest_json
FROM ai_candidate_decision d
JOIN knowledge_version v ON v.owner_id=d.owner_id AND v.item_id=d.target_item_id AND v.id=d.target_version_id
JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id
WHERE d.owner_id=#{owner} AND d.target_item_id=#{itemId} AND d.status='ADOPTED'
  AND v.version_number <=#{through}
AND v.version_number < #{before}
ORDER BY v.version_number DESC LIMIT #{limit}

SELECT owner_id,task_id,candidate_id,status,relation_id,content_json,created_at,supplement_id
FROM ai_relation_decision WHERE owner_id=#{owner} AND task_id=#{taskId}
ORDER BY CHAR_LENGTH(candidate_id),candidate_id

SELECT d.task_id,d.target_version_id,v.version_number AS target_version_number,d.created_at AS adopted_at,t.manifest_json
FROM ai_question_decision d
JOIN question_version v ON v.owner_id=d.owner_id AND v.question_id=d.target_question_id AND v.id=d.target_version_id
JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id
WHERE d.owner_id=#{owner} AND d.target_question_id=#{questionId} AND d.status='ADOPTED'
  AND v.version_number <=#{through}
AND v.version_number < #{before}
ORDER BY v.version_number DESC LIMIT #{limit}

SELECT d.task_id,d.target_version_id,v.version_number AS target_version_number,d.created_at AS adopted_at,t.manifest_json
FROM ai_expression_decision d
JOIN preparation_item i ON i.owner_id=d.owner_id AND i.id=d.target_item_id AND i.kind='EXPRESSION'
JOIN preparation_version v ON v.owner_id=d.owner_id AND v.item_id=d.target_item_id AND v.id=d.target_version_id
JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id AND t.purpose='EXPRESSION_DRAFT'
WHERE d.owner_id=#{owner} AND d.target_item_id=#{expressionId} AND d.status='ADOPTED'
  AND v.version_number <=#{through}
AND v.version_number < #{before}
ORDER BY v.version_number DESC LIMIT #{limit}
